#!/usr/bin/env python3
"""Exercise the production preview NSView with generated bytes and no windows."""
from pathlib import Path
import hashlib
import os
import struct
import subprocess
import tempfile
import zlib

PROJECT = Path(__file__).resolve().parents[1]
SOURCE = PROJECT / "QuickLookExtension/NativeArchivePreview.swift"
RUNNER = r'''
import AppKit
import Foundation
import PDFKit
import ImageIO
import CoreGraphics
import Darwin

// Only the archive engine's error type is stubbed. All classification, limits,
// thumbnail creation and installed preview views come from production source.
enum NativeArchive {
    struct Failure: LocalizedError {
        var message: String
        var errorDescription: String? { message }
    }
}

let root = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
var checks = 0
func expect(_ value: @autoclosure () throws -> Bool, _ label: String) throws {
    guard try value() else { throw NativeArchive.Failure(message: label) }
    checks += 1
}
func component() -> NativeArchivePreview { NativeArchivePreview(frame: NSRect(x: 0, y: 0, width: 480, height: 320)) }
func bytes(_ name: String) throws -> Data { try Data(contentsOf: root.appendingPathComponent(name)) }
func rejects(_ data: Data, filename: String, message: String) throws {
    let preview = component()
    var failure: Error?
    do { try preview.show(data: data, filename: filename) } catch { failure = error }
    try expect(failure != nil, "unexpected preview success: " + filename)
    try expect(failure?.localizedDescription.contains(message) == true, "wrong preview rejection: " + filename)
    try expect(preview.subviews.isEmpty, "rejected bytes installed a view: " + filename)
}
func text(_ value: String, filename: String) throws {
    let preview = component()
    try preview.show(data: Data(value.utf8), filename: filename)
    guard let scroll = preview.subviews.first as? NSScrollView,
          let document = scroll.documentView as? NSTextView else { throw NativeArchive.Failure(message: "text did not install the native listing view") }
    try expect(document.string == value, "text bytes changed")
    try expect(!document.isEditable && document.isSelectable, "text preview became editable or unselectable")
    try expect(preview.window == nil, "component unexpectedly created a window")
}
func pdf(_ count: Int) throws -> Data {
    let data = NSMutableData()
    var box = CGRect(x: 0, y: 0, width: 64, height: 64)
    guard let consumer = CGDataConsumer(data: data as CFMutableData),
          let context = CGContext(consumer: consumer, mediaBox: &box, nil) else { throw NativeArchive.Failure(message: "PDF fixture creation failed") }
    for _ in 0..<count {
        context.beginPDFPage(nil); context.setFillColor(CGColor(gray: 1, alpha: 1)); context.fill(box); context.endPDFPage()
    }
    context.closePDF()
    return data as Data
}

do {
    try text("中文预览：安全文本\n第二行\t末尾。\r\n", filename: "中文.txt")
    try text("ASCII text <tag> & literal content\n\tTabbed line\r\n", filename: "plain.txt")
    // Filename is not a substitute for byte-level type recognition.
    try text("ordinary UTF-8 text, despite its suffix\n", filename: "text.png")
    try text("", filename: "empty.txt")
    let png = try bytes("valid.png")
    let image = component()
    try image.show(data: png, filename: "image.bin")
    guard let imageView = image.subviews.first as? NSImageView else { throw NativeArchive.Failure(message: "valid PNG did not install an image view") }
    try expect(imageView.image != nil && imageView.image!.size.width == 2 && imageView.image!.size.height == 2, "PNG thumbnail dimensions differ")
    try expect(image.window == nil, "image component unexpectedly created a window")
    for name in ["corrupt.png", "too-wide.png", "too-many-pixels.png"] {
        let data = try bytes(name)
        guard let source = CGImageSourceCreateWithData(data as CFData, nil) else { throw NativeArchive.Failure(message: "image fixture has no ImageIO source") }
        try expect(CGImageSourceGetType(source) != nil, "invalid recognized-image fixture: " + name)
        try rejects(data, filename: name, message: "图片无法读取")
    }
    let asciiImage = Data("GIF89aABCDEFGHIJKLMNOPQRSTUVWX".utf8)
    guard let asciiSource = CGImageSourceCreateWithData(asciiImage as CFData, nil) else { throw NativeArchive.Failure(message: "GIF fixture has no ImageIO source") }
    try expect(CGImageSourceGetType(asciiSource) != nil && String(data: asciiImage, encoding: .utf8) != nil, "damaged GIF must be both recognized and valid UTF-8")
    try rejects(asciiImage, filename: "damaged-utf8.gif", message: "图片无法读取")
    try rejects(Data([0xff, 0xfe, 0xfd, 0x80]), filename: "binary.bin", message: "此内容不能安全")
    try rejects(Data("unsafe\u{0001}control".utf8), filename: "control.txt", message: "此内容不能安全")
    try rejects(Data("unsafe\u{0000}control".utf8), filename: "nul.txt", message: "此内容不能安全")
    try rejects(Data(repeating: 65, count: 2 * 1_024 * 1_024 + 1), filename: "large.txt", message: "此内容不能安全")
    try rejects(Data(repeating: 65, count: 16 * 1_024 * 1_024 + 1), filename: "oversized.bin", message: "16 MiB")
    let smallPDF = try pdf(1)
    let pdfView = component()
    try pdfView.show(data: smallPDF, filename: "pdf.bin")
    try expect((pdfView.subviews.first as? PDFView)?.document?.pageCount == 1, "PDF preview lost its document")
    try expect(pdfView.window == nil, "PDF component unexpectedly created a window")
    let boundaryPDF = component()
    try boundaryPDF.show(data: pdf(100), filename: "boundary.pdf")
    try expect((boundaryPDF.subviews.first as? PDFView)?.document?.pageCount == 100, "100-page PDF boundary changed")
    try rejects(pdf(101), filename: "too-many-pages.pdf", message: "100 页")
    try rejects(Data("%PDF-1.7\nnot a PDF document".utf8), filename: "damaged.pdf", message: "PDF 无法读取")
    print("PASS: \(checks) production Quick Look preview component checks; generated bytes, no windows or business actions")
} catch {
    fputs("PREVIEW_COMPONENT_FAILURE: \(error.localizedDescription)\n", stderr)
    exit(1)
}
'''


def png(width, height, compressed):
    def chunk(kind, data):
        return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", zlib.crc32(kind + data) & 0xffffffff)
    header = struct.pack(">IIBBBBB", width, height, 8, 6, 0, 0, 0)
    return b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", header) + chunk(b"IDAT", compressed) + chunk(b"IEND", b"")


def main():
    source_bytes = SOURCE.read_bytes()
    source_sha = hashlib.sha256(source_bytes).hexdigest()
    with tempfile.TemporaryDirectory(prefix="gaocaozuo-ql-preview-", dir="/private/tmp") as temporary:
        root = Path(temporary)
        os.chmod(root, 0o700)
        (root / "NativeArchivePreview.swift").write_bytes(source_bytes)
        (root / "main.swift").write_text(RUNNER)
        pixels = b"\x00" + b"\xff\x00\x00\xff" * 2
        (root / "valid.png").write_bytes(png(2, 2, zlib.compress(pixels * 2)))
        (root / "corrupt.png").write_bytes(png(2, 2, b"invalid DEFLATE data"))
        (root / "too-wide.png").write_bytes(png(10001, 1, zlib.compress(b"")))
        (root / "too-many-pixels.png").write_bytes(png(10000, 4001, zlib.compress(b"")))
        executable = root / "preview-component"
        subprocess.run([
            "swiftc", "-swift-version", "5", "-Xfrontend", "-disable-sandbox", "-O",
            "-target", "arm64-apple-macos14.0", "-module-cache-path", str(root / "cache"),
            str(root / "NativeArchivePreview.swift"), str(root / "main.swift"),
            "-framework", "AppKit", "-framework", "PDFKit", "-framework", "ImageIO",
            "-framework", "CoreGraphics", "-o", str(executable),
        ], check=True, timeout=60)
        subprocess.run([str(executable), str(root)], check=True, timeout=30)
    if hashlib.sha256(SOURCE.read_bytes()).hexdigest() != source_sha:
        raise RuntimeError("production preview source changed during component verification")


if __name__ == "__main__":
    main()
